package org.jkiss.dbeaver.teststudio.core;
import com.google.gson.*;import java.nio.charset.StandardCharsets;import org.jkiss.dbeaver.teststudio.spi.TestReportProvider;
final class HtmlReportProvider implements TestReportProvider{public String format(){return "html";}public String extension(){return "html";}public byte[] generate(JsonObject run,JsonObject options){StringBuilder rows=new StringBuilder();for(JsonElement e:StudioJson.array(run,"steps")){JsonObject s=e.getAsJsonObject();rows.append("<tr><td>").append(h(StudioJson.string(s,"id",""))).append("</td><td>").append(h(StudioJson.string(s,"type",""))).append("</td><td>").append(h(StudioJson.string(s,"status",StudioJson.bool(s,"passed",false)?"passed":"failed"))).append("</td><td>").append(s.has("elapsed_ms")?String.format(java.util.Locale.ROOT,"%.1f",s.get("elapsed_ms").getAsDouble()):"").append("</td><td><pre>").append(h(summary(s))).append("</pre></td></tr>");}String title=h(StudioJson.string(run,"name","Test Studio Run"));String state=h(StudioJson.string(run,"state","unknown"));String html="<!doctype html><html><head><meta charset=\"utf-8\"><title>"+title+"</title><style>body{font-family:system-ui,sans-serif;margin:2rem}table{border-collapse:collapse;width:100%}th,td{border:1px solid #ccc;padding:.5rem;vertical-align:top}pre{white-space:pre-wrap;max-height:20rem;overflow:auto}.passed{color:green}.failed{color:#b00}</style></head><body><h1>"+title+"</h1><p>State: <strong class=\""+(StudioJson.bool(run,"passed",false)?"passed":"failed")+"\">"+state+"</strong></p><p>Run: "+h(StudioJson.string(run,"run_id",""))+"</p><table><thead><tr><th>Step</th><th>Type</th><th>Status</th><th>ms</th><th>Evidence</th></tr></thead><tbody>"+rows+"</tbody></table><h2>Cleanup</h2><pre>"+h(StudioJson.GSON.toJson(StudioJson.object(run,"cleanup")))+"</pre></body></html>";return html.getBytes(StandardCharsets.UTF_8);}private static String summary(JsonObject s){JsonObject c=s.deepCopy();c.remove("result");return StudioJson.GSON.toJson(c);}private static String h(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}}
